PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS password_reset_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_connections (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider TEXT NOT NULL CHECK(provider='google'), provider_account_id TEXT, access_token_ciphertext TEXT NOT NULL, refresh_token_ciphertext TEXT, expires_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id, provider));
CREATE TABLE IF NOT EXISTS properties (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, oauth_connection_id TEXT REFERENCES oauth_connections(id) ON DELETE SET NULL, ga4_property_id TEXT NOT NULL, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, deleted_at TEXT, UNIQUE(user_id, ga4_property_id));
CREATE TABLE IF NOT EXISTS daily_metrics (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, metric_date TEXT NOT NULL, sessions INTEGER NOT NULL, users INTEGER NOT NULL, engaged_sessions INTEGER NOT NULL, engagement_rate REAL NOT NULL, avg_engagement_seconds REAL NOT NULL, page_views INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(property_id,metric_date));
CREATE TABLE IF NOT EXISTS hourly_metrics (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, metric_hour TEXT NOT NULL, sessions INTEGER NOT NULL, engaged_sessions INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(property_id,metric_hour));
CREATE TABLE IF NOT EXISTS traffic_sources (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, metric_date TEXT NOT NULL, source TEXT NOT NULL, medium TEXT NOT NULL, sessions INTEGER NOT NULL, engagement_rate REAL NOT NULL, created_at TEXT NOT NULL, UNIQUE(property_id,metric_date,source,medium));
CREATE TABLE IF NOT EXISTS country_metrics (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, metric_date TEXT NOT NULL, country TEXT NOT NULL, sessions INTEGER NOT NULL, engagement_rate REAL NOT NULL, created_at TEXT NOT NULL, UNIQUE(property_id,metric_date,country));
CREATE TABLE IF NOT EXISTS risk_scores (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, score_date TEXT NOT NULL, score INTEGER, level TEXT NOT NULL, baseline_status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(property_id,score_date));
CREATE TABLE IF NOT EXISTS risk_factors (id TEXT PRIMARY KEY, risk_score_id TEXT NOT NULL REFERENCES risk_scores(id) ON DELETE CASCADE, type TEXT NOT NULL, points INTEGER NOT NULL, title TEXT NOT NULL, explanation TEXT NOT NULL, evidence_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS anomalies (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, type TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, details_json TEXT NOT NULL, occurred_at TEXT NOT NULL, reviewed_at TEXT, dismissed_at TEXT);
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, property_id TEXT REFERENCES properties(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, read_at TEXT, dismissed_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, paypal_subscription_id TEXT UNIQUE, plan TEXT NOT NULL DEFAULT 'free', status TEXT NOT NULL DEFAULT 'active', next_billing_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paypal_events (id TEXT PRIMARY KEY, event_id TEXT NOT NULL UNIQUE, event_type TEXT NOT NULL, payload_json TEXT NOT NULL, processed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tracker_sites (id TEXT PRIMARY KEY, property_id TEXT NOT NULL UNIQUE REFERENCES properties(id) ON DELETE CASCADE, public_id TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, disabled_at TEXT);
CREATE TABLE IF NOT EXISTS tracker_metrics (id TEXT PRIMARY KEY, tracker_site_id TEXT NOT NULL REFERENCES tracker_sites(id) ON DELETE CASCADE, metric_date TEXT NOT NULL, sessions INTEGER NOT NULL, low_interaction_sessions INTEGER NOT NULL, avg_duration_seconds REAL NOT NULL, created_at TEXT NOT NULL, UNIQUE(tracker_site_id,metric_date));
CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, prefix TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE, last_used_at TEXT, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, metadata_json TEXT NOT NULL, ip_hash TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_hash ON sessions(token_hash); CREATE INDEX IF NOT EXISTS idx_properties_user ON properties(user_id); CREATE INDEX IF NOT EXISTS idx_daily_property_date ON daily_metrics(property_id,metric_date); CREATE INDEX IF NOT EXISTS idx_alerts_user ON alerts(user_id,created_at); CREATE INDEX IF NOT EXISTS idx_anomalies_property ON anomalies(property_id,occurred_at);
